{"action":"sql","query":"SELECT COUNT(DISTINCT n.loan_id) AS cnt FROM svc_loan_notes n JOIN svc_loans l ON l.loan_id = n.loan_id WHERE l.product = 'auto' AND LOWER(n.note) LIKE '%hardship%';"}
